{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "srs-network://contracts/clarity-feedback.schema.json",
  "title": "Clarity Feedback",
  "description": "agents/re-reviewer.md's SECOND output, written next to its review.json at the task manifest's clarity_output_path: the srs-clarity judgment kept in srs-clarity's OWN vocabulary (유형 분류 / PASS-FAIL / 개선 제안 table), not remapped into review.schema.json's RE-* rule ids. review.schema.json is additionalProperties:false and deliberately axis-shaped, so this material has nowhere to live there -- and it is exactly what a later mode=publish run uploads verbatim into the CodeBeamer item's Clarity fields. Nothing here is ever re-judged at publish time: the verdict a leaf is published with is the one its last accepted review-re round actually produced.",
  "type": "object",
  "additionalProperties": false,
  "required": ["schema_version", "task_id", "input_fingerprint", "entries"],
  "properties": {
    "schema_version": {"type": "string", "minLength": 1},
    "task_id": {
      "type": "string",
      "minLength": 1,
      "description": "Echoed verbatim from the task manifest -- must equal the sibling review.json's task_id (same dispatch, two outputs)."
    },
    "input_fingerprint": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}$",
      "description": "Echoed verbatim from the task's input_fingerprint, same discipline as review.schema.json's own field. This is the BATCH fingerprint (all leaves of the round) and is therefore useless for per-leaf matching -- per-leaf matching uses entries[].leaf_content_fingerprint, which Python fills in."
    },
    "entries": {
      "type": "array",
      "minItems": 1,
      "description": "One entry per leaf the review-re task covered. A directory selection round reviews N leaves and must return N entries -- a leaf with no entry simply has no clarity result and will block a later clarity upload rather than be published with a guessed one.",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["leaf_uid", "overall_verdict", "req_pattern", "feedback_markdown"],
        "properties": {
          "leaf_uid": {
            "type": "string",
            "minLength": 1,
            "description": "The reviewed leaf's uid, exactly as it appears in that leaf file's front matter."
          },
          "overall_verdict": {
            "type": "string",
            "enum": ["PASS", "FAIL"],
            "description": "srs-clarity's 4대 기준 체크 result -- PASS only when all four criteria are O, per its own rule. Uploaded as-is into the item's `AI Clarity Review` field."
          },
          "req_pattern": {
            "type": "string",
            "enum": [
              "Mode & State Behavior",
              "Data Transformation & Logic",
              "Interface & Communication",
              "Non-Functional Constraints"
            ],
            "description": "srs-clarity's 유형 분류, one of its four exact names. Uploaded as-is into the item's `Req Pattern` field -- never translated, never abbreviated, or the field write is rejected by the tracker."
          },
          "feedback_markdown": {
            "type": "string",
            "minLength": 1,
            "description": "srs-clarity's COMPLETE analysis text for this leaf, exactly as it produced it -- 유형 분류 + 4대 기준 체크 + the 개선 제안 Markdown table, including the 개선 제안 table on a PASS (srs-clarity's own STEP 5A requires it). This whole string is what its uploader stores in the item's `AI Clarity Feedback` field; srs-clarity converts it to CodeBeamer wiki markup itself, so it is never converted, trimmed, or summarised here."
          },
          "leaf_content_fingerprint": {
            "type": "string",
            "pattern": "^[0-9a-f]{64}$",
            "description": "FILLED IN BY PYTHON (scripts/runtime/clarity_feedback.py::enrich) at accept time -- scripts/runtime/fingerprints.py::content_fingerprint of the leaf this entry judged. A submission that already carries this field is REJECTED: a delegate cannot compute it, so its presence means the value was invented, and an invented fingerprint would let stale clarity text be published against changed content. It is optional in this schema only so the submitted and the stored form share one contract."
          },
          "leaf_path": {
            "type": "string",
            "minLength": 1,
            "description": "FILLED IN BY PYTHON alongside leaf_content_fingerprint -- the leaf file this entry judged, as named in the task manifest. Same rejection rule applies to a submission that sets it."
          }
        }
      }
    }
  }
}

