import yaml, re

def parse_leaf(text):
    m = re.match(r'^---\n(.*?)\n---\n(.*)$', text, re.S)
    fm = yaml.safe_load(m.group(1))
    body = m.group(2)
    return fm, body

leaf_data = {}
for p, txt in file_contents.items():
    fm, body = parse_leaf(txt)
    leaf_data[fm['uid']] = {'path': p, 'fm': fm, 'body': body}

print(len(leaf_data))
# build param ownership map per L3 module
import collections
param_owner = collections.defaultdict(list)  # (l3, name) -> [uid,...]
for uid, d in leaf_data.items():
    l3 = d['fm']['id'].split('-')[2]
    for pd in (d['fm'].get('parameter_definition') or []):
        param_owner[(l3, pd['name'])].append(uid)

